'use strict';

// MODULES //

var maxn = require( '@stdlib/math/base/special/maxn' );
var max = require( '@stdlib/math/base/special/fast/max' );
var normalize = require( './normalize.js' );

/**
* Initialize the array on the bases of calculated require row and col.
*
* @private
* @name initialize
* @returns {void}
*/
function initialize() {
	var bckColorArr;
	var frdColorArr;
	var glyphArr;
	var val;
	var mx;
	var i;

	// x axis label space
	var x = 0;

	// y axis label space
	var y = 0;

	// z axis label space
	var z = 0;

	// w axis label space
	var w = 0;
	var j;

	x = 0;
	z = 0;
	this._plotArea = {};
	if ( this._axisDataObjs ) {
		// X axis
		if ( this._axisDataObjs[ 0 ].axis ) {
			mx = 0;

			// Resizing the normalizeLabels array
			this._axisDataObjs[ 0 ].normalizeLabels.length = this._axisDataObjs[ 0 ].rawLabels.length;
			for ( i = 0; i < this._axisDataObjs[ 0 ].rawLabels.length; i++ ) {
				val = normalize( this._axisDataObjs[ 0 ].rawLabels[ i ], this._axisDataObjs[ 0 ].labelFormate, 'graphemes' );
				this._axisDataObjs[ 0 ].normalizeLabels[ i ] = val;
				mx = max( mx, val.width );
			}

			if ( this._axisDataObjs[ 0 ].position === 'default' ) {
				x = mx + 1;

				// Setting x axis position after the tics label
				this._axisDataObjs[ 0 ].position = mx;
			}
			else {
				x = 0;
			}
		}

		// Y axis
		if ( this._axisDataObjs[ 1 ].axis ) {
			// Resizing the normalizeLabels array
			this._axisDataObjs[ 1 ].normalizeLabels.length = this._axisDataObjs[ 1 ].rawLabels.length;
			for ( i = 0; i < this._axisDataObjs[ 1 ].rawLabels.length; i++ ) {
				val = normalize( this._axisDataObjs[ 1 ].rawLabels[ i ], this._axisDataObjs[ 1 ].labelFormate, 'graphemes' );
				this._axisDataObjs[ 1 ].normalizeLabels[ i ] = val;
			}

			if ( this._axisDataObjs[ 1 ].position === 'default' ) {
				y = 2;

				// Setting y position on 1 ( 0 for the labels );
				this._axisDataObjs[ 1 ].position = 1;
			}
			else {
				y = 0;
			}
		}

		// Z Axis
		if ( this._axisDataObjs[ 2 ].axis ) {
			mx = 0;

			// Resizing the normalizeLabels array
			this._axisDataObjs[ 2 ].normalizeLabels.length = this._axisDataObjs[ 2 ].rawLabels.length;
			for ( i = 0; i < this._axisDataObjs[ 2 ].rawLabels.length; i++ ) {
				val = normalize( this._axisDataObjs[ 2 ].rawLabels[ i ], this._axisDataObjs[ 2 ].labelFormate, 'graphemes' );
				this._axisDataObjs[ 2 ].normalizeLabels[ i ] = val;
				mx = max( mx, val.width );
			}

			if ( this._axisDataObjs[ 2 ].position === 'default' ) {
				z = mx + 1;
				this._axisDataObjs[ 2 ].position = x + this.plotAreaWidth;
			}
			else {
				z = 0;
			}
		}

		// W axis
		if ( this._axisDataObjs[ 3 ].axis ) {
			// Resizing the normalizeLabels array
			this._axisDataObjs[ 3 ].normalizeLabels.length = this._axisDataObjs[ 3 ].rawLabels.length;
			for ( i = 0; i < this._axisDataObjs[ 3 ].rawLabels.length; i++ ) {
				val = normalize( this._axisDataObjs[ 3 ].rawLabels[ i ], this._axisDataObjs[ 3 ].labelFormate, 'graphemes' );
				this._axisDataObjs[ 3 ].normalizeLabels[ i ] = val;
			}

			if ( this._axisDataObjs[ 3 ].position === 'default' ) {
				w = 2;
				this._axisDataObjs[ 3 ].position = y + this._plotAreaHeight;
			}
			else {
				w = 0;
			}
		}
	}

	// Setting plot area
	this._plotArea.x = max( x - 1, 0 );
	this._plotArea.y = max( y - 1, 0 );
	this._plotArea.z = this._plotAreaWidth + x;
	this._plotArea.w = this._plotAreaHeight + y;

	// Setting height and width for the matrix array

	// Axis tics space + plotAreaHeight
	this._height = y + w + this._plotAreaHeight;
	this._width = x + z + this._plotAreaWidth;
	this._glyphMatrix = [];
	this._backgroundColorMatrix = [];
	this._foregroundColorMatrix = [];
	for ( i = 0; i < this._height; i++ ) {
		bckColorArr = new Array( this._width );
		frdColorArr = new Array( this._width );
		glyphArr = new Array( this._width );
		for ( j = 0; j < this._width; j++ ) {
			glyphArr[ j ] = this._glyph;
			bckColorArr[ j ] = this._backgroundColor;
			frdColorArr[ j ] = this.foregroundColor;
		}
		this._glyphMatrix.push( glyphArr );
		this._backgroundColorMatrix.push( bckColorArr );
		this._foregroundColorMatrix.push( frdColorArr );
	}
}

module.exports = initialize;
